/** Original replacement presets. No provider assets, hidden prompts or thumbnails are included. */
export const IMAGE_TOOL_LOCALES = ["zh-CN", "en", "zh-TW", "ja", "ko", "es", "fr", "de", "pt-BR", "ru", "ar", "hi"] as const;
export type ImageToolLocale = typeof IMAGE_TOOL_LOCALES[number];
export type ImageToolLocalizedText = Readonly<Record<ImageToolLocale, string>>;

export interface ImagePreset {
  readonly id: string;
  readonly names: ImageToolLocalizedText;
  /** Model-facing English is deliberate: UI names are localized separately. */
  readonly promptFragment: string;
}
export interface ImageStyleParameters {
  readonly contrast?: number;
  readonly saturation?: number;
  readonly vibrance?: number;
  readonly temperature?: number;
  readonly tint?: number;
  readonly clarity?: number;
  readonly shadows?: number;
  readonly highlights?: number;
}
export type ImagePresetJson = null | boolean | number | string | readonly ImagePresetJson[] | { readonly [key: string]: ImagePresetJson };
export interface ImageStylePreset extends ImagePreset {
  readonly categoryId: "animation" | "digital" | "cinema" | "drama" | "extended";
  readonly parameters?: ImageStyleParameters;
  /** Explicit visual components, beyond the menu label or an overall color grade. */
  readonly configuration: Readonly<Record<string, ImagePresetJson>>;
}
export interface ImageLightingLight {
  readonly role: "key" | "fill" | "rim" | "ambient" | "point";
  readonly position: string;
  readonly yawDegrees: number;
  readonly elevationDegrees: number;
  /** Relative artistic intensity, not a photometric measurement. */
  readonly intensity: number;
  readonly color: string;
  readonly hex: string;
}
export interface ImageLightingPreset extends ImagePreset {
  readonly sceneRotationY: number;
  readonly lights: readonly ImageLightingLight[];
}
export const IMAGE_POSE_JOINT_IDS = ["head", "neck", "leftShoulder", "rightShoulder", "leftElbow", "rightElbow", "leftHand", "rightHand", "spine", "leftHip", "rightHip", "leftKnee", "rightKnee", "leftFoot", "rightFoot"] as const;
export type ImagePoseJointId = typeof IMAGE_POSE_JOINT_IDS[number];
export interface ImagePoseJoint { readonly x: number; readonly y: number; readonly radius: number }
export interface ImagePosePreset extends ImagePreset {
  /** Compact diagram coordinates. These are UI guides, not a model control tensor. */
  readonly joints: Readonly<Record<ImagePoseJointId, ImagePoseJoint>>;
}
export interface ImagePaletteColor { readonly hex: string; readonly weight: number }
export interface ImagePalettePreset extends ImagePreset {
  readonly colors: readonly ImagePaletteColor[];
}

function names(...values: readonly [string, string, string, string, string, string, string, string, string, string, string, string]): ImageToolLocalizedText {
  return Object.freeze(Object.fromEntries(IMAGE_TOOL_LOCALES.map((locale, index) => [locale, values[index]]))) as ImageToolLocalizedText;
}

