/** Descriptive cinema names replace personal and franchise branding while preserving distinct grades. */
function cinemaNames(index: number, parameters: ImageStyleParameters): ImageToolLocalizedText {
  const temperature = (parameters.temperature ?? 0) >= 10 ? TEXT.warm : (parameters.temperature ?? 0) <= -10 ? TEXT.cool : TEXT.neutral;
  const contrast = (parameters.contrast ?? 0) < 0 ? TEXT.soft : (parameters.contrast ?? 0) >= 35 ? TEXT.dramatic : TEXT.balanced;
  return Object.freeze(Object.fromEntries(IMAGE_TOOL_LOCALES.map(locale => [locale, `${TEXT.cinema[locale]} ${String(index).padStart(2, "0")} · ${temperature[locale]} · ${contrast[locale]}`]))) as ImageToolLocalizedText;
}

/** UI names are complete in all supported locales; unknown runtime locales fall back to English. */
export function imagePresetName(preset: ImagePreset, locale: string = "en"): string {
  return IMAGE_TOOL_LOCALES.includes(locale as ImageToolLocale) ? preset.names[locale as ImageToolLocale] : preset.names.en;
}

function freezeTree<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) freezeTree(child);
    Object.freeze(value);
  }
  return value;
}

