function presetFor<T extends ImagePreset>(catalog: readonly T[], id: string, kind: string): T {
  const preset = catalog.find(candidate => candidate.id === id);
  if (!preset) throw new RangeError(`Unknown image ${kind} preset: ${id}`);
  return preset;
}
export function getImageStylePreset(id: string): ImageStylePreset { return presetFor(IMAGE_STYLE_PRESETS, id, "style"); }
export function getImageLightingPreset(id: string): ImageLightingPreset { return presetFor(IMAGE_LIGHTING_PRESETS, id, "lighting"); }
export function getImagePosePreset(id: string): ImagePosePreset { return presetFor(IMAGE_POSE_PRESETS, id, "pose"); }
export function getImagePalettePreset(id: string): ImagePalettePreset { return presetFor(IMAGE_PALETTE_PRESETS, id, "palette"); }
